// Dia a sincronizar: ayer en America/Guayaquil (UTC-05:00 fijo, sin horario de verano).
// Se puede forzar otro dia o un rango pasando { fecha } o { desde, hasta } al ejecutar
// manualmente, que es como se hace el backfill.
const entrada = $input.first()?.json ?? {};
const OFFSET_MS = 5 * 60 * 60 * 1000;

function fechaGye(d) {
  return new Date(d.getTime() - OFFSET_MS).toISOString().slice(0, 10);
}

let fechas = [];
if (entrada.desde && entrada.hasta) {
  for (let d = new Date(entrada.desde + 'T12:00:00Z'); fechaGye(d) <= entrada.hasta; d.setUTCDate(d.getUTCDate() + 1)) {
    fechas.push(fechaGye(d));
  }
} else if (entrada.fecha) {
  fechas = [entrada.fecha];
} else {
  const ayer = new Date(Date.now() - 24 * 60 * 60 * 1000);
  fechas = [fechaGye(ayer)];
}

// Ventana UTC del dia calendario de Guayaquil.
return fechas.map((fecha) => {
  const iniUtc = new Date(`${fecha}T00:00:00-05:00`).toISOString();
  const finUtc = new Date(new Date(`${fecha}T00:00:00-05:00`).getTime() + 86400000).toISOString();
  return { json: { fecha, iniUtc, finUtc } };
});

// Normaliza las cuatro respuestas de Google Health al contrato de
// /api/os/biometricas (ver apps/web/docs/contrato-biometricas.md).
// Se manda SOLO lo que vino de verdad: el endpoint mergea por fecha y un null
// explicito borraria un dato ya guardado.
const fecha = $('Calcular dia').first().json.fecha;
const dp = (nodo) => $(nodo).first().json?.dataPoints ?? [];

// Pasos: la API devuelve tramos intradiarios; el dia es la suma.
const pasos = dp('GH steps').reduce((acc, p) => acc + Number(p?.steps?.count ?? 0), 0);

// Sueno: minutos dormidos de las sesiones que TERMINAN en este dia.
const suenoMin = dp('GH sleep').reduce((acc, p) => acc + Number(p?.sleep?.summary?.minutesAsleep ?? 0), 0);

// FC en reposo: resumen diario, hay como mucho uno.
const fcRaw = dp('GH resting HR')[0]?.dailyRestingHeartRate?.beatsPerMinute;

// Peso: la API lo da en gramos, el OS lo guarda en kg. Si hubo varias
// mediciones, se toma la ultima.
const pesos = dp('GH weight');
const pesoG = pesos.length ? pesos[0]?.weight?.weightGrams : null;

const body = { fecha, fuente: 'google_health' };
if (pasos > 0) body.pasos = Math.round(pasos);
if (suenoMin > 0) body.sueno_min = Math.round(suenoMin);
if (fcRaw) body.fc_reposo = Math.round(Number(fcRaw));
if (pesoG) body.peso_kg = Math.round((Number(pesoG) / 1000) * 100) / 100;

// Payload crudo para auditoria: la API v4 esta evolucionando y el crudo permite
// reprocesar sin haber perdido nada.
body.raw = {
  steps: $('GH steps').first().json,
  sleep: $('GH sleep').first().json,
  restingHeartRate: $('GH resting HR').first().json,
  weight: $('GH weight').first().json,
};

// Sin ninguna metrica el endpoint responde 400. No es un error: es un dia sin datos.
const tieneMetrica = ['pasos', 'sueno_min', 'fc_reposo', 'peso_kg'].some((k) => k in body);
return [{ json: { body, tieneMetrica } }];
